 assert e['id'] not in seen;seen.add(e['id'])
 if e.get('log'):assert hashlib.sha256((root/'docs/evidence'/e['log']).read_bytes()).hexdigest()==e['logSHA256'],e['id']
 if e.get('recipe'):assert hashlib.sha256((root/e['recipe']).read_bytes()).hexdigest()==e['stdinSHA256'],e['id']
 if e['id'].startswith('multidisk-native-'):
  for path,digest in e['fixtureDigests'].items():assert hashlib.sha256((root/path).read_bytes()).hexdigest()==digest
fixture=json.loads((base/'observed-fixture-20260907.json').read_text())
assert hashlib.sha256((base/'boot.S').read_bytes()).hexdigest()==fixture['assemblySHA256']
assert hashlib.sha256((base/'build.py').read_bytes()).hexdigest()==fixture['generatorSHA256']
scripts=list(base.rglob('*.py'))
for p in scripts:ast.parse(p.read_text(),filename=str(p))
