for r in tracker['requirements']:
 assert r['status']!='accepted' and not r['hardwareVerified'] and not r['released']
 assert all(e in seen for e in r['evidence'])
 for key in ('implementationPaths','tests'):
  for path in r[key]:assert (root/path).exists(),(r['id'],path)
documents=[root/'docs/evidence/multidisk-crash-run.md',base/'disposable-recorded-run/README.md',root/'docs/creation-cleanup.md',root/'docs/vm-creation.md',root/'docs/import-preparation.md',root/'docs/support-matrix.md']
for p in documents:
 for target in re.findall(r'\]\(([^)]+)\)',p.read_text()):
  if '://' not in target and not target.startswith('#'):assert (p.parent/target.split('#')[0]).exists(),(str(p),target)
assert subprocess.check_output(['git','ls-files','-ci','--exclude-standard'])==b''
