 assert subprocess.run(['git','check-ignore','-q',p]).returncode==0,p
for p in ('tests/fixtures/import/multidisk-probe/boot.S','tests/fixtures/import/multidisk-probe/build.py','docs/evidence/logs/multidisk-native-crash-001.log'):
 assert subprocess.run(['git','check-ignore','-q',p]).returncode==1,p
tracked=subprocess.check_output(['git','ls-files','-z']).decode().split('\0')
assert not any(p.startswith(('.virmill-local/','.tools/','build/','dist/')) for p in tracked)
print(json.dumps({'recordedEntriesChecked':len(records),'uniqueIDs':len(seen),'logAndRecipeHashes':'passed','pythonFixtureSyntaxFiles':len(scripts),'recordedGeneratorSources':'passed','requirementPathAndDocumentLinks':'passed','all71NotAccepted':True,'ignoredMediaBuildsAndPrivateConfig':'passed','hardwareTestsExecutedByThisCheck':False}))
